public void bfs(Node root) {
    Queue<Node> q = new LinkedList<>();
    q.add(root);
    while(!q.isEmpty()) {
        Node curr = q.poll();
        for(Node n : curr.neighbors) q.add(n);
    }
}

public void dfs(Node node, Set<Node> visited) {
    if(visited.contains(node)) return;
    visited.add(node);
    for(Node n : node.neighbors) dfs(n, visited);
}

